  function giroChioma(cs) { var b = [1e9, 1e9, -1e9, -1e9]; cs.forEach(function (c) { b[0] = Math.min(b[0], c[0] - c[2]); b[1] = Math.min(b[1], c[1] - c[2]); b[2] = Math.max(b[2], c[0] + c[2]); b[3] = Math.max(b[3], c[1] + c[2]); }); return b; }
