        for (j = 0; j <= 10; j++) a.push(pt(-s0 + 2 * s0 * j / 10, t0, d));
        for (j = 1; j < 8; j++) { th2 = j / 8 * Math.PI; a.push(pt(s0 + .07 * Math.sin(th2), tm - hr * Math.cos(th2), d)); }
        for (j = 10; j >= 0; j--) a.push(pt(-s0 + 2 * s0 * j / 10, t1, d));
