    [[-.105, -.055], [.105, -.055], [-.105, .055], [.105, .055]].forEach(function (g) { var pp = P(g[0], g[1], 0); s += ell(pp[0], pp[1] + .2, 1.4, .7, "#16181b"); });   // i piedini
