      var F = [G * .7071, G * .7071, 0], n0 = nrm(sub([0, 0, 1], mul(f[1], f[1][2]))), np = sub(F, mul(f[1], dot(F, f[1])));   // la foglia pende sul bordo e gira un po' la faccia verso chi guarda (davanti e anche da dietro)
