    for (i = 1; i < 5; i++) { var nd = S([-.012, -.012, Z0 + i * .055]); bs += tratto("M" + q2(nd[0] - .45, nd[1]) + " l.9,0", "#8a6a3a", .35); }
    var cl = S([-.012, -.012, .3]);
