    s += tondo(0, 0, [[21.8, .19], [22.6, .199], [23.8, .2], [24.4, .194]], [[0, "#ffffff"], [.4, "#f1f3f5"], [.8, "#c3ccd2"], [1, "#94a0a9"]], 1.7);
