    sil += "<path d='" + dz + "' fill='none' stroke='§' stroke-width='2.6' stroke-linecap='round' stroke-linejoin='round'/>" + ell(x, y - 9, 6.2, 7.3, "§", "stroke='§' stroke-width='1.5'") + ell(x, y, 4.5, 4.2, "§", "stroke='§' stroke-width='1.3'");
