    var sil = PARTI.map(function (x) { return x.sil; }).join(""), gancio = rett(27.4, 0, 7.2, 1.7, .7, lin("gm", [[0, "#dee2e6"], [1, "#868e96"]], 0, 0, 0, 1), bordo(L, .7)) + tratto("M31,1.6 L31,3.4 Q31,5 32.4,4.6", "#868e96", 1.1);
    var gr = "transform='rotate(-4 31 2)'";
