    s += rett(0, 0, MW, 15.5, lin("nmq", [[0, "#3e0b26"], [1, "#1f0516"]], 0, 0, 0, 1)) + cromo(0, 2.6, "ncr1") + cromo(13, 2.6, "ncr2") + ombraSotto(15.6, 4, .45);
    for (i = 0; i < 8; i++) s += lampadina(3.875 + i * 7.75, 7.8, notte || i % 2 === 0, notte);
