    s += ombraSotto(116.6, 3, .25) + rett(0, 96.6, MW, 2.4, "#f2f5fb") + rett(0, 101.4, MW, 9, lin("sst", [[0, "#ffffff"], [.7, "#eef1f8"], [1, "#c9d0e0"]], 0, 0, 0, 1)) + rett(0, 110.4, MW, 1.4, "#c8202f") + rett(0, 114.2, MW, 2.4, "#f2f5fb") + rett(0, 101.4, MW, .5, "#fff");
