      [25, 75].forEach(function (x) { s += cer(x, y + 3.6, .55, "#6a4520") + cer(x, y + 8.9, .55, "#6a4520") + cer(x - .15, y + 3.45, .2, "#fff", op(.6)) + cer(x - .15, y + 8.75, .2, "#fff", op(.6)); });
